import SchemaBuilder from '@pothos/core';

const builder = new SchemaBuilder({});

builder.queryType({
  fields: (t) => ({
    nonNullableField: t.field({
      type: 'String',
      nullable: false,
      resolve: () => 'Gina',
    }),
    nonNullableString: t.string({
      nullable: false,
      resolve: () => 'Gina',
    }),
    nonNullableList: t.field({
      type: ['String'],
      nullable: false,
      resolve: () => ['Gina', 'James'],
    }),
    sparseList: t.field({
      type: ['String'],
      nullable: {
        list: false,
        items: true,
      },
      resolve: () => [null],
    }),
  }),
});

export const schema = builder.toSchema();

defaultQuery:
query Nullability {
  nonNullableField
  nonNullableString
  nonNullableList
  sparseList
}

queries.query:
query Nullability {
  nonNullableField
  nonNullableString
  nonNullableList
  sparseList
}
